1	package com.example.starter.domain;
2	
3	import org.junit.jupiter.api.Test;
4	
5	import java.util.List;
6	import java.util.Map;
7	import java.util.TreeMap;
8	import java.util.concurrent.atomic.AtomicLong;
9	
10	import static org.assertj.core.api.Assertions.assertThat;
11	
12	/**
13	 * 锁定解析器单元测试：回溯、环依赖、撤回版本过滤与字典序解析顺序。
14	 */
15	class LockResolverTest {
16	
17	    /** 测试用快照构造器：按 name -> 版本（版本号，是否撤回，依赖列表）组织，版本降序排列。 */
18	    private static RepositorySnapshot snapshot(long version, Object... groups) {
19	        Map<String, List<ArtifactVersion>> map = new TreeMap<>();
20	        AtomicLong id = new AtomicLong(1);
21	        for (int i = 0; i < groups.length; i += 2) {
22	            String name = (String) groups[i];
23	            @SuppressWarnings("unchecked")
24	            List<TestVersion> versions = (List<TestVersion>) groups[i + 1];
25	            List<ArtifactVersion> list = versions.stream()
26	                    .map(v -> new ArtifactVersion(id.getAndIncrement(), name, v.version(),
27	                            v.withdrawn(), v.deps()))
28	                    .toList();
29	            map.put(name, list);
30	        }
31	        return new RepositorySnapshot(version, map);
32	    }
33	
34	    private record TestVersion(int version, boolean withdrawn, List<DependencyRange> deps) {
35	    }
36	
37	    private static TestVersion v(int version, DependencyRange... deps) {
38	        return new TestVersion(version, false, List.of(deps));
39	    }
40	
41	    private static TestVersion w(int version, DependencyRange... deps) {
42	        return new TestVersion(version, true, List.of(deps));
43	    }
44	
45	    private static DependencyRange dep(String name, int min, int max) {
46	        return new DependencyRange(name, min, max);
47	    }
48	
49	    @Test
50	    void resolvesSingleRootWithoutDependencies() {
51	        RepositorySnapshot s = snapshot(0, "app", List.of(v(1)));
52	        assertThat(LockResolver.resolve(s, "app", 1))
53	                .isEqualTo(Map.of("app", 1));
54	    }
55	
56	    @Test
57	    void requiresBacktrackingWhenHighestCandidateConflictsLater() {
58	        // app:1 -> B[1,2] 且 C[1,1]；B2 -> C[2,2]（与 C1 冲突），必须回退到 B1。
59	        RepositorySnapshot s = snapshot(0,
60	                "app", List.of(v(1, dep("b", 1, 2), dep("c", 1, 1))),
61	                "b", List.of(v(2, dep("c", 2, 2)), v(1)),
62	                "c", List.of(v(1)));
63	
64	        Map<String, Integer> result = LockResolver.resolve(s, "app", 1);
65	        assertThat(result).isNotNull();
66	        assertThat(result).containsEntry("app", 1).containsEntry("b", 1).containsEntry("c", 1);
67	    }
68	
69	    @Test
70	    void cannotGreedilyTakeHighestVersionAcrossMultipleLevels() {
71	        // app -> a[1,2]；a2 -> b[2,2]，a1 -> b[1,1]；b2 已撤回，b1 有效。
72	        // 贪心取 a2 将失败，必须回退到 a1/b1。
73	        RepositorySnapshot s = snapshot(0,
74	                "app", List.of(v(1, dep("a", 1, 2))),
75	                "a", List.of(v(2, dep("b", 2, 2)), v(1, dep("b", 1, 1))),
76	                "b", List.of(w(2), v(1)));
77	
78	        assertThat(LockResolver.resolve(s, "app", 1))
79	                .isEqualTo(Map.of("app", 1, "a", 1, "b", 1));
80	    }
81	
82	    @Test
83	    void detectsUnsatisfiableCycleAndReturnsNull() {
84	        // 根 app:1 固定，a1 -> app[2,2]，但 app 只能是 1，环冲突不可行。
85	        RepositorySnapshot s = snapshot(0,
86	                "app", List.of(v(1, dep("a", 1, 1)), v(2)),
87	                "a", List.of(v(1, dep("app", 2, 2))));
88	
89	        assertThat(LockResolver.resolve(s, "app", 1)).isNull();
90	    }
91	
92	    @Test
93	    void supportsConsistentCycle() {
94	        // app:1 -> a[1,1]，a1 -> app[1,1]：环但区间互相满足。
95	        RepositorySnapshot s = snapshot(0,
96	                "app", List.of(v(1, dep("a", 1, 1)), v(2, dep("a", 1, 1))),
97	                "a", List.of(v(1, dep("app", 1, 1))));
98	
99	        assertThat(LockResolver.resolve(s, "app", 1))
100	                .isEqualTo(Map.of("app", 1, "a", 1));
101	    }
102	
103	    @Test
104	    void selfDependencyMustMatchFixedRootVersion() {
105	        RepositorySnapshot s = snapshot(0,
106	                "app", List.of(v(2, dep("app", 2, 2)), v(1, dep("app", 1, 1))));
107	        assertThat(LockResolver.resolve(s, "app", 1)).isEqualTo(Map.of("app", 1));
108	        assertThat(LockResolver.resolve(s, "app", 2)).isEqualTo(Map.of("app", 2));
109	    }
110	
111	    @Test
112	    void selfDependencyMismatchIsInfeasible() {
113	        RepositorySnapshot s = snapshot(0,
114	                "app", List.of(v(1, dep("app", 2, 2)), v(2)));
115	        assertThat(LockResolver.resolve(s, "app", 1)).isNull();
116	    }
117	
118	    @Test
119	    void skipsWithdrawnCandidates() {
120	        // b2 已撤回，只能取 b1。
121	        RepositorySnapshot s = snapshot(0,
122	                "app", List.of(v(1, dep("b", 1, 2))),
123	                "b", List.of(w(2), v(1)));
124	        assertThat(LockResolver.resolve(s, "app", 1))
125	                .isEqualTo(Map.of("app", 1, "b", 1));
126	    }
127	
128	    @Test
129	    void returnsNullWhenAllCandidatesWithdrawn() {
130	        RepositorySnapshot s = snapshot(0,
131	                "app", List.of(v(1, dep("b", 1, 2))),
132	                "b", List.of(w(2), w(1)));
133	        assertThat(LockResolver.resolve(s, "app", 1)).isNull();
134	    }
135	
136	    @Test
137	    void returnsNullWhenDependencyNameMissing() {
138	        RepositorySnapshot s = snapshot(0,
139	                "app", List.of(v(1, dep("ghost", 1, 1))));
140	        assertThat(LockResolver.resolve(s, "app", 1)).isNull();
141	    }
142	
143	    @Test
144	    void intersectsRangesFromMultipleSelectedArtifacts() {
145	        // app -> b[1,3] 且 c1 -> b[3,3]，交集只剩 b3。
146	        RepositorySnapshot s = snapshot(0,
147	                "app", List.of(v(1, dep("b", 1, 3), dep("c", 1, 1))),
148	                "b", List.of(v(3), v(2), v(1)),
149	                "c", List.of(v(1, dep("b", 3, 3))));
150	        assertThat(LockResolver.resolve(s, "app", 1))
151	                .isEqualTo(Map.of("app", 1, "b", 3, "c", 1));
152	    }
153	
154	    @Test
155	    void emptyRangeIntersectionIsInfeasible() {
156	        // app -> b[1,2] 且 c1 -> b[3,3]，交集为空。
157	        RepositorySnapshot s = snapshot(0,
158	                "app", List.of(v(1, dep("b", 1, 2), dep("c", 1, 1))),
159	                "b", List.of(v(3), v(2), v(1)),
160	                "c", List.of(v(1, dep("b", 3, 3))));
161	        assertThat(LockResolver.resolve(s, "app", 1)).isNull();
162	    }
163	
164	    @Test
165	    void resolvesDependenciesInLexicographicNameOrder() {
166	        // 字典序下 zeta 先于 zeta-child 被解析；构造需要跨层回溯的场景。
167	        // app -> zeta[1,2]；zeta2 -> mid[2,2]（mid2 撤回），zeta1 -> mid[1,1]。
168	        RepositorySnapshot s = snapshot(0,
169	                "app", List.of(v(1, dep("zeta", 1, 2))),
170	                "zeta", List.of(v(2, dep("mid", 2, 2)), v(1, dep("mid", 1, 1))),
171	                "mid", List.of(w(2), v(1)));
172	        assertThat(LockResolver.resolve(s, "app", 1))
173	                .isEqualTo(Map.of("app", 1, "zeta", 1, "mid", 1));
174	    }
175	
176	    @Test
177	    void resultKeysAreSortedByName() {
178	        RepositorySnapshot s = snapshot(0,
179	                "root", List.of(v(1, dep("zlib", 1, 1), dep("alib", 1, 1))),
180	                "zlib", List.of(v(1)),
181	                "alib", List.of(v(1)));
182	        Map<String, Integer> result = LockResolver.resolve(s, "root", 1);
183	        assertThat(result).isNotNull();
184	        assertThat(result.keySet()).containsExactly("alib", "root", "zlib");
