package com.example.starter.api.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.Size;

/**
 * 制品版本许可证登记请求。
 *
 * @param license 许可证标识；未提供或为空表示清除登记并恢复为 UNKNOWN
 */
public record SetLicenseRequest(
        @NotBlank String name,
        @Positive int version,
        @Size(max = 64) String license) {
}

package com.example.starter.api.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.PositiveOrZero;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 命名空间许可证策略配置请求（整体替换允许集合）。
 *
 * @param namespace       命名空间名称（等于制品名称）
 * @param expectedVersion 期望的当前策略版本：无策略时必须为 0，首次创建；其后为当前版本
 * @param rejectUnknown   是否拒绝未登记许可证（UNKNOWN）
 * @param allowedLicenses 允许的许可证标识集合，重复标识会被去重
 */
public record SetPolicyRequest(
        @NotBlank String namespace,
        @NotNull @PositiveOrZero Long expectedVersion,
        @NotNull Boolean rejectUnknown,
        @Size(max = 50) List<@NotBlank @Size(max = 64) String> allowedLicenses) {

    public SetPolicyRequest {
        if (allowedLicenses == null) {
            allowedLicenses = List.of();
        } else {
            allowedLicenses = List.copyOf(allowedLicenses);
        }
    }
}

package com.example.starter.api.dto;

import java.time.Instant;
import java.util.List;

/**
 * 命名空间许可证策略视图，allowedLicenses 按字典序排列。
 *
 * @param version          当前策略版本号
 * @param rejectUnknown    是否拒绝 UNKNOWN
 * @param allowedLicenses  允许的许可证标识集合（排序）
 * @param updatedAt        最后修改时间，UTC
 */
public record PolicyResponse(
        String namespace,
        long version,
        boolean rejectUnknown,
        List<String> allowedLicenses,
        Instant updatedAt) {
}

package com.example.starter.api.dto;

/**
 * 锁文件中单个名称对应的精确版本及锁定时固化的许可证快照。
 *
 * @param name          被锁定制品名称
 * @param version       被锁定精确版本号
 * @param license       锁定时登记的许可证标识；null 表示当时为 UNKNOWN
 * @param policyVersion 锁定时命名空间策略版本；当时无策略为 0
 */
public record LockEntryResponse(String name, int version, String license, long policyVersion) {
}

