            "SELECT namespace, version, reject_unknown FROM namespace_policy WHERE namespace = ?",
            (rs, n) -> new PolicyRow(rs.getString("namespace"), rs.getLong("version"),
                    rs.getInt("reject_unknown") == 1),
            namespace);
    if (rows.isEmpty()) {
        return null;
